$secure = Read-Host -Prompt 'AgentPulse API key' -AsSecureString; $bstr = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure); $key = [Runtime.InteropServices.Marshal]::PtrToStringBSTR($bstr); [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($bstr); function ApTestReparse($p) { $i = Get-Item -LiteralPath $p -Force -ErrorAction SilentlyContinue; if (-not $i) { return $false }; if ($i.LinkType) { return $true }; return [bool]($i.Attributes -band [System.IO.FileAttributes]::ReparsePoint) }; function ApTestHardLink($p) { if (-not (Test-Path -LiteralPath $p)) { return $false }; try { $o = & fsutil hardlink list $p 2>$null; if ($LASTEXITCODE -ne 0 -or -not $o) { return $false }; return (@($o | Where-Object { $_.Trim().Length -gt 0 }).Count -gt 1) } catch { return $false } }; $d="$env:USERPROFILE\.agentpulse"; if (ApTestReparse $d) { Write-Error "refusing to write through a reparse point: $d" } else { New-Item -ItemType Directory -Force $d | Out-Null; icacls $d /inheritance:r /grant:r "$($env:USERNAME):(OI)(CI)F" | Out-Null; $f="$d\hook-auth-header"; if (ApTestHardLink $f) { Write-Error "refusing to write through a multiply-linked file: $f" } elseif (ApTestReparse $f) { Write-Error "refusing to write through a reparse point: $f" } else { $t="$f.$([guid]::NewGuid().ToString('N')).tmp"; Set-Content -NoNewline -Path $t -Value "Authorization: Bearer $key`n"; Move-Item -Force -Path $t -Destination $f; icacls $f /inheritance:r /grant:r "$($env:USERNAME):(R,W)" | Out-Null } }; $key = $null
